PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE customers (     id INTEGER PRIMARY KEY AUTOINCREMENT,     customer_name TEXT NOT NULL DEFAULT '',     brand_name TEXT NOT NULL DEFAULT '',     email TEXT NOT NULL UNIQUE,     phone TEXT NOT NULL DEFAULT '',     created_at TEXT NOT NULL,     updated_at TEXT NOT NULL );
CREATE TABLE quotations (     id INTEGER PRIMARY KEY AUTOINCREMENT,     quote_reference TEXT NOT NULL UNIQUE,     submission_reference TEXT,     customer_id INTEGER,     status TEXT NOT NULL DEFAULT 'draft' CHECK (         status IN (             'draft',             'sent',             'accepted',             'declined',             'expired',             'cancelled'         )     ),     customer_name TEXT NOT NULL DEFAULT '',     brand_name TEXT NOT NULL DEFAULT '',     customer_email TEXT NOT NULL DEFAULT '',     customer_phone TEXT NOT NULL DEFAULT '',     currency TEXT NOT NULL DEFAULT 'NGN',     issue_date TEXT NOT NULL,     expiry_date TEXT NOT NULL,     production_timeline TEXT NOT NULL DEFAULT '',     payment_terms TEXT NOT NULL DEFAULT '',     notes TEXT NOT NULL DEFAULT '',     subtotal INTEGER NOT NULL DEFAULT 0,     discount INTEGER NOT NULL DEFAULT 0,     delivery_fee INTEGER NOT NULL DEFAULT 0,     tax INTEGER NOT NULL DEFAULT 0,     grand_total INTEGER NOT NULL DEFAULT 0,     created_at TEXT NOT NULL,     updated_at TEXT NOT NULL, sent_at TEXT, send_count INTEGER NOT NULL DEFAULT 0, resend_email_id TEXT, public_token TEXT, viewed_at TEXT, last_viewed_at TEXT, view_count INTEGER NOT NULL DEFAULT 0, accepted_at TEXT, declined_at TEXT, responded_at TEXT, response_type TEXT, response_comment TEXT, response_reason TEXT,     FOREIGN KEY (submission_reference)         REFERENCES "submissions_old"(reference)         ON DELETE SET NULL,     FOREIGN KEY (customer_id)         REFERENCES customers(id)         ON DELETE SET NULL );
CREATE TABLE quotation_items (     id INTEGER PRIMARY KEY AUTOINCREMENT,     quotation_id INTEGER NOT NULL,     item_order INTEGER NOT NULL DEFAULT 1,     description TEXT NOT NULL,     details TEXT NOT NULL DEFAULT '',     quantity REAL NOT NULL CHECK (quantity > 0),     unit_price INTEGER NOT NULL CHECK (unit_price >= 0),     line_total INTEGER NOT NULL CHECK (line_total >= 0),     created_at TEXT NOT NULL,     updated_at TEXT NOT NULL,     FOREIGN KEY (quotation_id)         REFERENCES quotations(id)         ON DELETE CASCADE );
CREATE TABLE quotation_activity (     id INTEGER PRIMARY KEY AUTOINCREMENT,     quotation_id INTEGER NOT NULL,     activity_type TEXT NOT NULL,     title TEXT NOT NULL,     details TEXT,     actor TEXT NOT NULL DEFAULT 'system',     created_at TEXT NOT NULL,     FOREIGN KEY (quotation_id) REFERENCES quotations(id) ON DELETE CASCADE );
CREATE TABLE invoices (     id INTEGER PRIMARY KEY AUTOINCREMENT,     invoice_reference TEXT NOT NULL UNIQUE,     quotation_id INTEGER,     customer_id INTEGER,     status TEXT NOT NULL DEFAULT 'draft',     customer_name TEXT,     brand_name TEXT,     customer_email TEXT,     customer_phone TEXT,     currency TEXT NOT NULL DEFAULT 'NGN',     issue_date TEXT NOT NULL,     due_date TEXT,     subtotal REAL NOT NULL DEFAULT 0,     discount REAL NOT NULL DEFAULT 0,     delivery_fee REAL NOT NULL DEFAULT 0,     tax REAL NOT NULL DEFAULT 0,     grand_total REAL NOT NULL DEFAULT 0,     amount_paid REAL NOT NULL DEFAULT 0,     balance_due REAL NOT NULL DEFAULT 0,     payment_terms TEXT,     payment_instructions TEXT,     customer_note TEXT,     internal_note TEXT,     created_at TEXT NOT NULL,     updated_at TEXT NOT NULL, public_token TEXT, sent_at TEXT, send_count INTEGER NOT NULL DEFAULT 0, resend_email_id TEXT, viewed_at TEXT, view_count INTEGER NOT NULL DEFAULT 0, payment_confirmation_status TEXT, payment_confirmation_amount REAL, payment_confirmation_reference TEXT, payment_confirmation_note TEXT, payment_confirmation_at TEXT, payment_confirmation_file_key TEXT, payment_confirmation_file_name TEXT, payment_confirmation_file_type TEXT, payment_confirmation_file_size INTEGER,     FOREIGN KEY (quotation_id) REFERENCES quotations(id) ON DELETE SET NULL,     FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE SET NULL );
CREATE TABLE invoice_items (     id INTEGER PRIMARY KEY AUTOINCREMENT,     invoice_id INTEGER NOT NULL,     item_order INTEGER NOT NULL DEFAULT 0,     description TEXT NOT NULL,     details TEXT,     quantity REAL NOT NULL DEFAULT 1,     unit_price REAL NOT NULL DEFAULT 0,     line_total REAL NOT NULL DEFAULT 0,     created_at TEXT NOT NULL,     updated_at TEXT NOT NULL,     FOREIGN KEY (invoice_id) REFERENCES invoices(id) ON DELETE CASCADE );
CREATE TABLE invoice_activity (     id INTEGER PRIMARY KEY AUTOINCREMENT,     invoice_id INTEGER NOT NULL,     activity_type TEXT NOT NULL,     title TEXT NOT NULL,     details TEXT,     actor TEXT NOT NULL DEFAULT 'system',     created_at TEXT NOT NULL,     FOREIGN KEY (invoice_id) REFERENCES invoices(id) ON DELETE CASCADE );
CREATE TABLE invoice_payments (     id INTEGER PRIMARY KEY AUTOINCREMENT,     invoice_id INTEGER NOT NULL,     receipt_reference TEXT NOT NULL UNIQUE,     receipt_token TEXT NOT NULL UNIQUE,     amount REAL NOT NULL,     payment_date TEXT NOT NULL,     payment_method TEXT NOT NULL,     payment_reference TEXT,     notes TEXT,     recorded_by TEXT NOT NULL DEFAULT 'admin',     receipt_sent_at TEXT,     receipt_send_count INTEGER NOT NULL DEFAULT 0,     resend_email_id TEXT,     created_at TEXT NOT NULL,     updated_at TEXT NOT NULL,     FOREIGN KEY (invoice_id) REFERENCES invoices(id) ON DELETE CASCADE );
CREATE TABLE orders (     id INTEGER PRIMARY KEY AUTOINCREMENT,     order_reference TEXT NOT NULL UNIQUE,     invoice_id INTEGER NOT NULL UNIQUE,     quotation_id INTEGER,     customer_id INTEGER,     customer_name TEXT,     brand_name TEXT,     customer_email TEXT,     customer_phone TEXT,     status TEXT NOT NULL DEFAULT 'new',     priority TEXT NOT NULL DEFAULT 'normal',     assigned_to TEXT,     design_status TEXT NOT NULL DEFAULT 'not_started',     production_status TEXT NOT NULL DEFAULT 'not_started',     payment_status TEXT NOT NULL DEFAULT 'unpaid',     production_deadline TEXT,     expected_delivery_date TEXT,     delivery_method TEXT,     delivery_address TEXT,     customer_instructions TEXT,     internal_notes TEXT,     created_at TEXT NOT NULL,     updated_at TEXT NOT NULL,     completed_at TEXT, portal_enabled INTEGER NOT NULL DEFAULT 0, portal_token TEXT, client_progress_stage TEXT, client_progress_note TEXT, portal_activated_at TEXT, portal_updated_at TEXT, portal_expires_at TEXT,     FOREIGN KEY (invoice_id) REFERENCES invoices(id) ON DELETE RESTRICT,     FOREIGN KEY (quotation_id) REFERENCES quotations(id) ON DELETE SET NULL,     FOREIGN KEY (customer_id) REFERENCES customers(id) ON DELETE SET NULL );
CREATE TABLE order_items (     id INTEGER PRIMARY KEY AUTOINCREMENT,     order_id INTEGER NOT NULL,     item_order INTEGER NOT NULL DEFAULT 0,     description TEXT NOT NULL,     details TEXT,     quantity REAL NOT NULL DEFAULT 0,     unit_price REAL NOT NULL DEFAULT 0,     line_total REAL NOT NULL DEFAULT 0,     production_notes TEXT,     created_at TEXT NOT NULL,     updated_at TEXT NOT NULL,     FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE );
CREATE TABLE order_activity (     id INTEGER PRIMARY KEY AUTOINCREMENT,     order_id INTEGER NOT NULL,     activity_type TEXT NOT NULL,     title TEXT NOT NULL,     details TEXT,     actor TEXT NOT NULL DEFAULT 'admin',     created_at TEXT NOT NULL,     FOREIGN KEY (order_id) REFERENCES orders(id) ON DELETE CASCADE );
CREATE TABLE project_artwork_reviews (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            project_reference TEXT NOT NULL UNIQUE,
            status TEXT NOT NULL DEFAULT 'pending_review',
            notes TEXT,
            reviewed_by TEXT,
            reviewed_at TEXT,
            created_at TEXT NOT NULL,
            updated_at TEXT NOT NULL,
            FOREIGN KEY (project_reference)
                REFERENCES "submissions_old"(reference)
                ON DELETE CASCADE
        );
CREATE TABLE submissions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,

    reference TEXT NOT NULL UNIQUE,

    submission_type TEXT NOT NULL
        CHECK (
            submission_type IN (
                'project',
                'contact',
                'sample_request'
            )
        ),

    status TEXT NOT NULL DEFAULT 'new'
        CHECK (
            status IN (
                'new',
                'reviewing',
                'quoted',
                'closed',

                'sample_requested',
                'sample_quoted',
                'sample_paid',
                'sample_in_production',
                'sample_ready',
                'sample_approved',
                'sample_revision'
            )
        ),

    customer_name TEXT NOT NULL DEFAULT '',
    brand_name TEXT NOT NULL DEFAULT '',
    email TEXT NOT NULL DEFAULT '',
    phone TEXT NOT NULL DEFAULT '',

    summary TEXT NOT NULL DEFAULT '',

    payload_json TEXT NOT NULL DEFAULT '{}',

    email_status TEXT NOT NULL DEFAULT 'pending'
        CHECK (
            email_status IN (
                'pending',
                'sent',
                'failed'
            )
        ),

    email_error TEXT NOT NULL DEFAULT '',

    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);
CREATE TABLE project_structure_reviews (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_reference TEXT NOT NULL UNIQUE,
    status TEXT NOT NULL DEFAULT 'pending_review',
    notes TEXT,
    reviewed_by TEXT,
    reviewed_at TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    FOREIGN KEY (project_reference)
        REFERENCES submissions(reference)
        ON DELETE CASCADE
);
CREATE TABLE sample_request_reviews (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    submission_reference TEXT NOT NULL UNIQUE,
    decision TEXT NOT NULL DEFAULT 'pending_review',
    internal_notes TEXT,
    customer_message TEXT,
    scope_reason TEXT,
    reviewed_by TEXT,
    reviewed_at TEXT,
    email_status TEXT NOT NULL DEFAULT 'not_sent',
    email_sent_at TEXT,
    email_send_count INTEGER NOT NULL DEFAULT 0,
    resend_email_id TEXT,
    email_error TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    FOREIGN KEY (submission_reference)
        REFERENCES submissions(reference)
        ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS "d1_migrations"(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_customers_brand ON customers(brand_name);
CREATE INDEX idx_quotations_submission ON quotations(submission_reference);
CREATE INDEX idx_quotations_customer ON quotations(customer_id);
CREATE INDEX idx_quotations_status ON quotations(status);
CREATE INDEX idx_quotations_created_at ON quotations(created_at DESC);
CREATE INDEX idx_quotation_items_quotation ON quotation_items(quotation_id, item_order);
CREATE INDEX idx_quotations_sent_at ON quotations(sent_at DESC);
CREATE UNIQUE INDEX idx_quotations_public_token ON quotations(public_token);
CREATE INDEX idx_quotation_activity_quotation ON quotation_activity(quotation_id, created_at DESC);
CREATE INDEX idx_invoices_status ON invoices(status);
CREATE INDEX idx_invoices_due_date ON invoices(due_date);
CREATE INDEX idx_invoices_quotation_id ON invoices(quotation_id);
CREATE INDEX idx_invoice_items_invoice_id ON invoice_items(invoice_id);
CREATE UNIQUE INDEX idx_invoices_public_token ON invoices(public_token);
CREATE INDEX idx_invoice_activity_invoice_id ON invoice_activity(invoice_id);
CREATE INDEX idx_invoice_activity_created_at ON invoice_activity(created_at);
CREATE INDEX idx_invoice_payments_invoice_id ON invoice_payments(invoice_id);
CREATE INDEX idx_invoice_payments_payment_date ON invoice_payments(payment_date);
CREATE INDEX idx_invoice_payments_receipt_token ON invoice_payments(receipt_token);
CREATE INDEX idx_orders_status ON orders(status);
CREATE INDEX idx_orders_deadline ON orders(production_deadline);
CREATE INDEX idx_orders_delivery_date ON orders(expected_delivery_date);
CREATE INDEX idx_order_items_order ON order_items(order_id);
CREATE INDEX idx_order_activity_order ON order_activity(order_id);
CREATE UNIQUE INDEX idx_orders_portal_token ON orders(portal_token);
CREATE INDEX idx_orders_portal_expiry ON orders(portal_enabled, completed_at);
CREATE INDEX idx_project_artwork_reviews_reference
        ON project_artwork_reviews(project_reference)
    ;
CREATE INDEX idx_submissions_created_at
    ON submissions(created_at DESC);
CREATE INDEX idx_submissions_status
    ON submissions(status);
CREATE INDEX idx_submissions_type
    ON submissions(submission_type);
CREATE INDEX idx_submissions_email
    ON submissions(email);
CREATE INDEX idx_project_structure_reviews_reference
ON project_structure_reviews(project_reference);
CREATE INDEX idx_sample_request_reviews_reference
ON sample_request_reviews(submission_reference);
